package main

import (
	"flag"
	"fmt"
	"strings"
)

func main() {
	shout := flag.Bool("shout", false, "upper case, with !")
	flag.Parse()
	name := "world"
	if flag.NArg() > 0 {
		name = flag.Arg(0)
	}
	g := "Hello, " + name
	if *shout {
		g = strings.ToUpper(g) + "!"
	}
	fmt.Println(g)
}
